package main; import "fmt"; import "strings"; import "github.com/charmbracelet/lipgloss"; func main() { frameWidth := 100; innerWidth := frameWidth - 6; text := strings.Repeat("-", innerWidth); s := lipgloss.NewStyle().Border(lipgloss.RoundedBorder()).Padding(1, 2); fmt.Printf("Inner is %d, Total is %d\n", lipgloss.Width(text), lipgloss.Width(s.Width(frameWidth - 2).Render(text))); }
